static void event_handler ( sysevent_t * event ) { nvlist_t * nvlist ; struct cmd * cmd ; nvlist = NULL ; if ( sysevent_get_attr_list ( event , & nvlist ) != 0 ) { syslog ( LOG_ERR , NO_NVLIST_ERR ) ; return ; } if ( ( cmd = alloc_cmd ( nvlist ) ) != NULL ) { ( void ) mutex_lock ( & cmd_list_lock ) ; if ( cmd_list == NULL ) { cmd_list = cmd ; cmd_tail = cmd ; } else { cmd_tail -> cmd_next = cmd ; cmd_tail = cmd ; } cmd -> cmd_next = NULL ; ( void ) cond_signal ( & cmd_list_cv ) ; ( void ) mutex_unlock ( & cmd_list_lock ) ; } } 